class Solution:
    def numberOfSpecialSubstrings(self, s: str) -> int:
        cnt = [0] * 26
        ans = 0
        j = 0
        for i, char in enumerate(s):
            idx = ord(char) - ord('a')
            cnt[idx] += 1
            while cnt[idx] > 1:
                cnt[ord(s[j]) - ord('a')] -= 1
                j += 1
            ans += (i - j + 1)
        return ans

class Solution {
public:
    int numberOfSpecialSubstrings(string s) {
        vector<int> cnt(26, 0);
        int ans = 0, j = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            int idx = s[i] - 'a';
            cnt[idx]++;
            while (cnt[idx] > 1) {
                cnt[s[j] - 'a']--;
                j++;
            }
            ans += (i - j + 1);
        }
        return ans;
    }
};

class Solution {
    public int numberOfSpecialSubstrings(String s) {
        int[] cnt = new int[26];
        int ans = 0, j = 0;
        for (int i = 0; i < s.length(); i++) {
            int idx = s.charAt(i) - 'a';
            cnt[idx]++;
            while (cnt[idx] > 1) {
                cnt[s.charAt(j) - 'a']--;
                j++;
            }
            ans += (i - j + 1);
        }
        return ans;
    }
}

var numberOfSpecialSubstrings = function(s) {
    const cnt = new Array(26).fill(0);
    let ans = 0, j = 0;
    for (let i = 0; i < s.length; i++) {
        const idx = s.charCodeAt(i) - 97;
        cnt[idx]++;
        while (cnt[idx] > 1) {
            cnt[s.charCodeAt(j) - 97]--;
            j++;
        }
        ans += (i - j + 1);
    }
    return ans;
};
